import os

for root, dirs, files in os.walk("."):
    # Skip hidden directories like .git and __pycache__
    dirs[:] = [d for d in dirs if not d.startswith(".") and d != "__pycache__"]
    for f in files:
        if f.startswith("."):
            continue
        full = os.path.join(root, f)
        print(f"{full} ({os.path.getsize(full)} bytes)")
